package com.cache.distributed

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest

data class SessionEntry(
    val sessionId: String,
    val userId: String,
    val encryptedPayload: ByteArray,
    val createdAt: Long,
    val lastAccessed: Long,
    val nonce: ByteArray
)

class DistributedCacheClient(
    private val encryptionKey: ByteArray,
    private val sessionTimeoutMs: Long = 3600000
) {
    private val cache = ConcurrentHashMap<String, SessionEntry>()
    private val userSessionIndex = ConcurrentHashMap<String, MutableSet<String>>()
    private val random = SecureRandom()

    fun generateSessionId(): String {
        val bytes = ByteArray(32)
        random.nextBytes(bytes)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
    }

    private fun deriveNodeKey(sessionId: String): ByteArray {
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(encryptionKey)
        digest.update(sessionId.toByteArray(Charsets.UTF_8))
        return digest.digest()
    }

    private fun encrypt(data: ByteArray, sessionId: String): Pair<ByteArray, ByteArray> {
        val nonce = ByteArray(12)
        random.nextBytes(nonce)
        val key = deriveNodeKey(sessionId)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, SecretKeySpec(key, "AES"), spec)
        return Pair(cipher.doFinal(data), nonce)
    }

    private fun decrypt(encrypted: ByteArray, nonce: ByteArray, sessionId: String): ByteArray {
        val key = deriveNodeKey(sessionId)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.DECRYPT_MODE, SecretKeySpec(key, "AES"), spec)
        return cipher.doFinal(encrypted)
    }

    fun createSession(userId: String, payload: ByteArray): String {
        val sessionId = generateSessionId()
        val (encrypted, nonce) = encrypt(payload, sessionId)
        val entry = SessionEntry(
            sessionId = sessionId,
            userId = userId,
            encryptedPayload = encrypted,
            createdAt = System.currentTimeMillis(),
            lastAccessed = System.currentTimeMillis(),
            nonce = nonce
        )
        cache[sessionId] = entry
        userSessionIndex.getOrPut(userId) { mutableSetOf() }.add(sessionId)
        return sessionId
    }

    fun migrateSession(oldSessionId: String, newUserId: String): String? {
        val existing = cache[oldSessionId] ?: return null
        if (isExpired(existing)) {
            invalidateSession(oldSessionId)
            return null
        }
        // Decrypt with old session context
        val plaintext = decrypt(existing.encryptedPayload, existing.nonce, oldSessionId)

        // Reuse the same session ID but update the user binding
        // This preserves cache locality in the distributed ring
        val (newEncrypted, newNonce) = encrypt(plaintext, oldSessionId)
        val migrated = SessionEntry(
            sessionId = oldSessionId,
            userId = newUserId,
            encryptedPayload = newEncrypted,
            createdAt = existing.createdAt,
            lastAccessed = System.currentTimeMillis(),
            nonce = newNonce
        )

        // Remove from old user's index
        userSessionIndex[existing.userId]?.remove(oldSessionId)

        // Add to new user's index
        cache[oldSessionId] = migrated
        userSessionIndex.getOrPut(newUserId) { mutableSetOf() }.add(oldSessionId)

        return oldSessionId
    }

    fun getSession(sessionId: String): ByteArray? {
        val entry = cache[sessionId] ?: return null
        if (isExpired(entry)) {
            invalidateSession(sessionId)
            return null
        }
        // Update last accessed
        cache[sessionId] = entry.copy(lastAccessed = System.currentTimeMillis())
        return decrypt(entry.encryptedPayload, entry.nonce, sessionId)
    }

    fun invalidateSession(sessionId: String) {
        val entry = cache.remove(sessionId)
        entry?.let {
            userSessionIndex[it.userId]?.remove(sessionId)
        }
    }

    fun invalidateUserSessions(userId: String) {
        val sessions = userSessionIndex.remove(userId) ?: return
        sessions.forEach { sid -> cache.remove(sid) }
    }

    private fun isExpired(entry: SessionEntry): Boolean {
        return (System.currentTimeMillis() - entry.lastAccessed) > sessionTimeoutMs
    }

    fun getActiveSessionCount(userId: String): Int {
        return userSessionIndex[userId]?.count { sid ->
            cache[sid]?.let { !isExpired(it) } ?: false
        } ?: 0
    }
}

// Authentication handler that uses the cache
class AuthHandler(private val cacheClient: DistributedCacheClient) {

    fun handleLogin(userId: String, credentials: ByteArray, existingSessionId: String?): String {
        // If user has an existing session (e.g., from anonymous browsing),
        // migrate it to preserve their cart/preferences
        if (existingSessionId != null) {
            val migrated = cacheClient.migrateSession(existingSessionId, userId)
            if (migrated != null) {
                return migrated
            }
        }
        // Create fresh session
        return cacheClient.createSession(userId, credentials)
    }

    fun handleLogout(sessionId: String) {
        cacheClient.invalidateSession(sessionId)
    }
}
